export const envelope = [32, 34, 20];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const sy = (dy) => seatY + dy;

  // 3D grid buffer for precise bounds safety and single-pass emission
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function fillBox(x0, y0, z0, x1, y1, z1, block) {
    const minX = Math.min(x0, x1), maxX = Math.max(x0, x1);
    const minY = Math.min(y0, y1), maxY = Math.max(y0, y1);
    const minZ = Math.min(z0, z1), maxZ = Math.max(z0, z1);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  // --- Theme Extraction & Block Palette ---
  const stoneP = api.theme.stone?.primary || "minecraft:deepslate_bricks";
  const stoneA = api.theme.stone?.accent || "minecraft:polished_blackstone_bricks";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:deepslate_brick_stairs";
  const stoneSlab = api.theme.stone?.slab || "minecraft:deepslate_brick_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:deepslate_brick_wall";

  const plinth = api.theme.ground?.plinth || "minecraft:polished_blackstone";
  const pave = api.theme.ground?.pavement || "minecraft:deepslate_tiles";
  const groundStairs = api.theme.ground?.stairs || "minecraft:deepslate_tile_stairs";
  const groundSlab = api.theme.ground?.slab || "minecraft:deepslate_tile_slab";

  const woodPlanks = api.theme.wood?.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme.wood?.log || "minecraft:dark_oak_log";
  const woodFence = api.theme.wood?.fence || "minecraft:dark_oak_fence";

  const roofSolid = api.theme.roof?.solid || "minecraft:blackstone";
  const roofStairs = api.theme.roof?.stairs || "minecraft:blackstone_stairs";
  const roofSlab = api.theme.roof?.slab || "minecraft:blackstone_slab";

  // Specialized volcanic hold materials
  const magma = "minecraft:magma_block";
  const gilded = "minecraft:gilded_blackstone";
  const cryingObsidian = "minecraft:crying_obsidian";
  const ironBars = "minecraft:iron_bars";
  const anvilN = "minecraft:anvil[facing=north]";
  const anvilE = "minecraft:anvil[facing=east]";
  const soulCampfire = "minecraft:soul_campfire[lit=true]";
  const campfire = "minecraft:campfire[lit=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";
  const soulLanternHang = "minecraft:soul_lantern[hanging=true]";

  function st(base, facing, half = "bottom") {
    const id = base.split("[")[0];
    return `${id}[facing=${facing},half=${half}]`;
  }

  function sl(base, type = "bottom") {
    const id = base.split("[")[0];
    return `${id}[type=${type}]`;
  }

  // =========================================================================
  // 1. BACKGROUND MOUNTAIN CLIFF & ROCK STRATA (Z = 13..19, dy = 0..27)
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 13; z < D; z++) {
      for (let dy = 0; dy <= 27; dy++) {
        let b = stoneP;
        if (dy % 6 === 0 || dy % 6 === 1) b = stoneA;
        else if (dy % 11 === 0) b = roofSolid;
        else if ((x + dy + z) % 17 === 0) b = gilded;
        set(x, sy(dy), z, b);
      }
    }
  }

  // Mountain flanks projecting forward at the far wings (X=0..2, X=29..31, Z=7..12)
  for (let dy = 0; dy <= 26; dy++) {
    for (let z = 7; z <= 12; z++) {
      for (let x of [0, 1, 2, 29, 30, 31]) {
        let b = (dy % 4 === 0) ? stoneA : stoneP;
        set(x, sy(dy), z, b);
      }
    }
  }

  // =========================================================================
  // 2. GRAND ENTRANCE TUNNEL & INTERIOR VAULT (X = 13..18, Z = 9..18)
  // =========================================================================
  for (let x = 13; x <= 18; x++) {
    for (let z = 9; z <= 18; z++) {
      // Floor at dy = 2
      let floorBlock = pave;
      if (x === 15 || x === 16) {
        floorBlock = magma; // Central glowing magma channel down the hall
      } else if (x === 13 || x === 18) {
        floorBlock = plinth;
      }
      set(x, sy(2), z, floorBlock);

      // Hollow vault interior
      for (let dy = 3; dy <= 11; dy++) {
        set(x, sy(dy), z, "minecraft:air");
      }

      // Vaulted stone ceiling
      let ceilingDy = 12;
      if (x === 13 || x === 18) ceilingDy = 10;
      else if (x === 14 || x === 17) ceilingDy = 11;
      else ceilingDy = 12;

      set(x, sy(ceilingDy), z, stoneA);
      for (let dy = ceilingDy + 1; dy <= 13; dy++) {
        set(x, sy(dy), z, stoneP);
      }
    }
  }

  // Hallway Vault Ribs & Sconces (Z = 11, 14, 17)
  for (let z of [11, 14, 17]) {
    set(13, sy(3), z, st(stoneStairs, "east", "bottom"));
    set(13, sy(4), z, stoneWall);
    set(13, sy(5), z, stoneWall);
    set(13, sy(6), z, st(stoneStairs, "east", "top"));
    set(13, sy(7), z, soulLanternHang);

    set(18, sy(3), z, st(stoneStairs, "west", "bottom"));
    set(18, sy(4), z, stoneWall);
    set(18, sy(5), z, stoneWall);
    set(18, sy(6), z, st(stoneStairs, "west", "top"));
    set(18, sy(7), z, soulLanternHang);

    // Transverse ceiling rib
    set(14, sy(11), z, st(stoneStairs, "east", "top"));
    set(15, sy(12), z, sl(stoneSlab, "bottom"));
    set(16, sy(12), z, sl(stoneSlab, "bottom"));
    set(17, sy(11), z, st(stoneStairs, "west", "top"));
  }

  // =========================================================================
  // 3. FORECOURT, GRAND STAIRS & TERRACE (Z = 0..8, dy = 0..3)
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z <= 8; z++) {
      if (x >= 12 && x <= 19) {
        // Central grand entrance staircase
        if (z === 0 || z === 1) {
          set(x, sy(0), z, st(groundStairs, "north"));
        } else if (z === 2 || z === 3) {
          set(x, sy(1), z, st(groundStairs, "north"));
          set(x, sy(0), z, plinth);
        } else if (z === 4 || z === 5) {
          set(x, sy(2), z, (x === 15 || x === 16) ? magma : pave);
          set(x, sy(1), z, plinth);
          set(x, sy(0), z, plinth);
        } else {
          set(x, sy(2), z, (x === 15 || x === 16) ? magma : pave);
          set(x, sy(1), z, plinth);
          set(x, sy(0), z, plinth);
        }
      } else {
        // Flanking terrace pavement
        if (z <= 5) {
          set(x, sy(0), z, pave);
          if (z >= 3) {
            set(x, sy(1), z, pave);
            set(x, sy(0), z, plinth);
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. THE GRAND GATE PORTAL & ARCHES (X = 10..21, dy = 2..23, Z = 4..9)
  // =========================================================================
  // Outer Gate Buttress Columns (X=10..11 and X=20..21, Z=5..8, dy=2..18)
  for (let dy = 2; dy <= 18; dy++) {
    for (let z = 5; z <= 8; z++) {
      for (let x of [10, 11, 20, 21]) {
        let b = (dy % 3 === 0) ? stoneA : stoneP;
        if (z === 5 && (x === 11 || x === 20) && dy >= 4 && dy <= 15) {
          b = (dy % 2 === 0) ? magma : gilded; // Glowing rune column
        }
        set(x, sy(dy), z, b);
      }
    }
  }

  // Inner Gate Jambs (X=12 and X=19, Z=6..8, dy=2..13)
  for (let dy = 2; dy <= 13; dy++) {
    for (let z = 6; z <= 8; z++) {
      set(12, sy(dy), z, stoneP);
      set(19, sy(dy), z, stoneP);
    }
    set(12, sy(dy), 5, st(stoneStairs, "east"));
    set(19, sy(dy), 5, st(stoneStairs, "west"));
  }

  // Clear Portal Open Air (X=13..18, dy=3..13, Z=5..8)
  for (let x = 13; x <= 18; x++) {
    for (let dy = 3; dy <= 13; dy++) {
      for (let z = 5; z <= 8; z++) {
        set(x, sy(dy), z, "minecraft:air");
      }
    }
  }

  // Massive Raised Portcullis (Z = 8, dy = 6..14)
  for (let x = 13; x <= 18; x++) {
    for (let dy = 6; dy <= 14; dy++) {
      set(x, sy(dy), 8, ironBars);
    }
    if (x === 13 || x === 15 || x === 16 || x === 18) {
      set(x, sy(5), 8, ironBars); // Portcullis teeth
    }
  }

  // Iron-Banded Heavy Timber Gates (Z = 9, partially open)
  for (let dy = 3; dy <= 10; dy++) {
    set(13, sy(dy), 9, woodLog);
    set(14, sy(dy), 9, (dy === 4 || dy === 7 || dy === 9) ? ironBars : woodPlanks);
    set(17, sy(dy), 9, (dy === 4 || dy === 7 || dy === 9) ? ironBars : woodPlanks);
    set(18, sy(dy), 9, woodLog);
    set(15, sy(dy), 9, "minecraft:air");
    set(16, sy(dy), 9, "minecraft:air");
  }

  // Inner Arch (Z = 6..7)
  set(13, sy(13), 6, st(stoneStairs, "east", "bottom"));
  set(13, sy(13), 7, st(stoneStairs, "east", "bottom"));
  set(18, sy(13), 6, st(stoneStairs, "west", "bottom"));
  set(18, sy(13), 7, st(stoneStairs, "west", "bottom"));
  set(14, sy(14), 6, st(stoneStairs, "east", "bottom"));
  set(14, sy(14), 7, st(stoneStairs, "east", "bottom"));
  set(17, sy(14), 6, st(stoneStairs, "west", "bottom"));
  set(17, sy(14), 7, st(stoneStairs, "west", "bottom"));
  set(15, sy(15), 6, sl(stoneSlab, "bottom"));
  set(15, sy(15), 7, sl(stoneSlab, "bottom"));
  set(16, sy(15), 6, sl(stoneSlab, "bottom"));
  set(16, sy(15), 7, sl(stoneSlab, "bottom"));
  fillBox(12, sy(14), 6, 13, sy(16), 7, stoneP);
  fillBox(18, sy(14), 6, 19, sy(16), 7, stoneP);
  fillBox(14, sy(15), 6, 17, sy(16), 7, stoneP);

  // Middle Glowing Magma Rune Arch (North Face Z = 5)
  set(11, sy(15), 5, magma);
  set(12, sy(16), 5, gilded);
  set(13, sy(17), 5, magma);
  set(14, sy(17), 5, gilded);
  set(15, sy(18), 5, magma);
  set(16, sy(18), 5, magma);
  set(17, sy(17), 5, gilded);
  set(18, sy(17), 5, magma);
  set(19, sy(16), 5, gilded);
  set(20, sy(15), 5, magma);

  // Outer Heavy Corbelled Arch (Z = 4..5)
  set(10, sy(16), 4, st(stoneStairs, "east", "bottom"));
  set(11, sy(17), 4, st(stoneStairs, "east", "bottom"));
  set(12, sy(18), 4, st(stoneStairs, "east", "bottom"));
  set(13, sy(19), 4, st(stoneStairs, "east", "bottom"));
  set(14, sy(19), 4, sl(stoneSlab, "bottom"));
  set(17, sy(19), 4, sl(stoneSlab, "bottom"));
  set(18, sy(19), 4, st(stoneStairs, "west", "bottom"));
  set(19, sy(18), 4, st(stoneStairs, "west", "bottom"));
  set(20, sy(17), 4, st(stoneStairs, "west", "bottom"));
  set(21, sy(16), 4, st(stoneStairs, "west", "bottom"));

  fillBox(10, sy(17), 5, 12, sy(21), 6, stoneP);
  fillBox(19, sy(17), 5, 21, sy(21), 6, stoneP);
  fillBox(13, sy(20), 4, 18, sy(22), 6, stoneP);

  // Keystone Carved Dwarven Mask (X = 14..17, dy = 19..23, Z = 3..5)
  set(14, sy(23), 4, st(stoneStairs, "south", "top"));
  set(15, sy(23), 3, gilded);
  set(16, sy(23), 3, gilded);
  set(17, sy(23), 4, st(stoneStairs, "south", "top"));
  set(15, sy(23), 4, magma);
  set(16, sy(23), 4, magma);

  set(14, sy(22), 3, stoneA);
  set(15, sy(22), 3, cryingObsidian); // Glowing eyes
  set(16, sy(22), 3, cryingObsidian);
  set(17, sy(22), 3, stoneA);

  set(14, sy(21), 3, st(stoneStairs, "east", "bottom"));
  set(15, sy(21), 3, stoneP);
  set(16, sy(21), 3, stoneP);
  set(17, sy(21), 3, st(stoneStairs, "west", "bottom"));

  set(15, sy(20), 3, st(stoneStairs, "north", "top"));
  set(16, sy(20), 3, st(stoneStairs, "north", "top"));
  set(15, sy(19), 4, st(stoneStairs, "north", "top"));
  set(16, sy(19), 4, st(stoneStairs, "north", "top"));

  // =========================================================================
  // 5. TWIN COLOSSAL DWARF STATUES WITH WARHAMMERS (Left: cx=7, Right: cx=24)
  // =========================================================================
  function buildDwarfSentinel(cx) {
    // Pedestal (dy = 1..3, X = cx-3..cx+3, Z = 3..8)
    fillBox(cx - 3, sy(1), 3, cx + 3, sy(1), 8, plinth);
    fillBox(cx - 3, sy(2), 3, cx + 3, sy(2), 8, stoneA);
    for (let x = cx - 2; x <= cx + 2; x++) {
      set(x, sy(2), 3, (x % 2 === 0) ? magma : gilded);
    }
    for (let x = cx - 3; x <= cx + 3; x++) {
      set(x, sy(3), 3, st(stoneStairs, "north", "top"));
      set(x, sy(3), 8, st(stoneStairs, "south", "top"));
    }
    for (let z = 4; z <= 7; z++) {
      set(cx - 3, sy(3), z, st(stoneStairs, "west", "top"));
      set(cx + 3, sy(3), z, st(stoneStairs, "east", "top"));
      fillBox(cx - 2, sy(3), z, cx + 2, sy(3), z, pave);
    }

    // Boots (dy = 4..5)
    fillBox(cx - 2, sy(4), 4, cx - 1, sy(4), 6, plinth);
    set(cx - 2, sy(4), 3, st(stoneStairs, "north", "bottom"));
    set(cx - 1, sy(4), 3, st(stoneStairs, "north", "bottom"));
    fillBox(cx - 2, sy(5), 4, cx - 1, sy(5), 5, stoneP);

    fillBox(cx + 1, sy(4), 4, cx + 2, sy(4), 6, plinth);
    set(cx + 1, sy(4), 3, st(stoneStairs, "north", "bottom"));
    set(cx + 2, sy(4), 3, st(stoneStairs, "north", "bottom"));
    fillBox(cx + 1, sy(5), 4, cx + 2, sy(5), 5, stoneP);

    // Greaves & Kneecaps (dy = 6..7)
    fillBox(cx - 2, sy(6), 4, cx - 1, sy(7), 6, stoneP);
    fillBox(cx + 1, sy(6), 4, cx + 2, sy(7), 6, stoneP);
    set(cx - 2, sy(7), 3, gilded);
    set(cx - 1, sy(7), 3, st(stoneStairs, "north", "bottom"));
    set(cx + 1, sy(7), 3, st(stoneStairs, "north", "bottom"));
    set(cx + 2, sy(7), 3, gilded);

    // Armored Skirt & Mail Tunic (dy = 8..9)
    fillBox(cx - 2, sy(8), 4, cx + 2, sy(9), 7, stoneP);
    for (let x = cx - 2; x <= cx + 2; x++) {
      set(x, sy(8), 3, (x === cx) ? magma : stoneA);
      set(x, sy(9), 3, stoneA);
    }

    // Belt & Glowing Buckle (dy = 10)
    fillBox(cx - 2, sy(10), 4, cx + 2, sy(10), 7, stoneA);
    set(cx - 2, sy(10), 3, stoneA);
    set(cx - 1, sy(10), 3, gilded);
    set(cx, sy(10), 3, magma);
    set(cx + 1, sy(10), 3, gilded);
    set(cx + 2, sy(10), 3, stoneA);

    // Heavy Torso & Back Rock Merge (dy = 11..15)
    fillBox(cx - 2, sy(11), 4, cx + 2, sy(15), 7, stoneP);
    fillBox(cx - 2, sy(11), 8, cx + 2, sy(15), 12, stoneP);

    // Giant Pauldrons (dy = 14..16)
    fillBox(cx - 3, sy(14), 4, cx - 3, sy(15), 6, stoneA);
    set(cx - 3, sy(16), 4, st(stoneStairs, "west", "bottom"));
    set(cx - 3, sy(16), 5, sl(stoneSlab, "bottom"));
    set(cx - 3, sy(16), 6, st(stoneStairs, "west", "bottom"));

    fillBox(cx + 3, sy(14), 4, cx + 3, sy(15), 6, stoneA);
    set(cx + 3, sy(16), 4, st(stoneStairs, "east", "bottom"));
    set(cx + 3, sy(16), 5, sl(stoneSlab, "bottom"));
    set(cx + 3, sy(16), 6, st(stoneStairs, "east", "bottom"));

    // Arms & Stone Gauntlets (dy = 12..14)
    set(cx - 3, sy(12), 4, stoneP);
    set(cx - 3, sy(13), 4, stoneP);
    set(cx + 3, sy(12), 4, stoneP);
    set(cx + 3, sy(13), 4, stoneP);
    set(cx - 2, sy(13), 3, st(stoneStairs, "east", "bottom"));
    set(cx - 1, sy(13), 2, stoneA);
    set(cx + 2, sy(13), 3, st(stoneStairs, "west", "bottom"));
    set(cx + 1, sy(13), 2, stoneA);
    set(cx - 1, sy(12), 2, st(stoneStairs, "north", "top"));
    set(cx + 1, sy(12), 2, st(stoneStairs, "north", "top"));

    // Colossal Upright Warhammer
    for (let dy = 4; dy <= 17; dy++) {
      set(cx, sy(dy), 2, woodFence);
    }
    set(cx, sy(13), 2, gilded); // Gripping hands

    // Hammer Head (dy = 18..21, Z = 1..3, X = cx-2..cx+2)
    fillBox(cx - 1, sy(18), 1, cx + 1, sy(21), 3, roofSolid);
    set(cx, sy(19), 2, magma);
    set(cx, sy(20), 2, magma);
    set(cx - 2, sy(19), 2, st(roofStairs, "west", "bottom"));
    set(cx - 2, sy(20), 2, st(roofStairs, "west", "top"));
    set(cx + 2, sy(19), 2, st(roofStairs, "east", "bottom"));
    set(cx + 2, sy(20), 2, st(roofStairs, "east", "top"));
    set(cx, sy(19), 1, magma);
    set(cx, sy(20), 1, magma);
    set(cx - 1, sy(19), 1, st(roofStairs, "north", "bottom"));
    set(cx + 1, sy(19), 1, st(roofStairs, "north", "bottom"));
    set(cx - 1, sy(20), 1, st(roofStairs, "north", "top"));
    set(cx + 1, sy(20), 1, st(roofStairs, "north", "top"));
    set(cx, sy(22), 2, sl(roofSlab, "bottom"));
    set(cx - 1, sy(22), 2, st(roofStairs, "east", "bottom"));
    set(cx + 1, sy(22), 2, st(roofStairs, "west", "bottom"));

    // Braided Dwarven Beard with Gold Rings (dy = 11..16, Z = 3)
    set(cx, sy(16), 3, stoneA);
    set(cx - 1, sy(16), 3, stoneP);
    set(cx + 1, sy(16), 3, stoneP);

    set(cx, sy(15), 3, stoneA);
    set(cx - 1, sy(15), 3, stoneP);
    set(cx + 1, sy(15), 3, stoneP);

    set(cx, sy(14), 3, gilded); // Gold beard clasp
    set(cx - 1, sy(14), 3, stoneA);
    set(cx + 1, sy(14), 3, stoneA);

    set(cx, sy(13), 3, stoneA);
    set(cx - 1, sy(13), 3, stoneP);
    set(cx + 1, sy(13), 3, stoneP);

    set(cx, sy(12), 3, gilded); // Lower beard clasp
    set(cx - 1, sy(12), 3, stoneA);
    set(cx + 1, sy(12), 3, stoneA);

    set(cx, sy(11), 3, st(stoneStairs, "north", "top"));
    set(cx - 1, sy(11), 3, st(stoneStairs, "north", "top"));
    set(cx + 1, sy(11), 3, st(stoneStairs, "north", "top"));

    // Head, Face & Deep Sockets (dy = 16..18, Z = 4..6)
    fillBox(cx - 2, sy(16), 4, cx + 2, sy(18), 6, stoneP);
    set(cx, sy(17), 3, stoneP); // Nose
    set(cx - 1, sy(17), 3, cryingObsidian); // Eye
    set(cx + 1, sy(17), 3, cryingObsidian); // Eye
    set(cx - 1, sy(18), 3, st(stoneStairs, "north", "bottom"));
    set(cx, sy(18), 3, gilded);
    set(cx + 1, sy(18), 3, st(stoneStairs, "north", "bottom"));
    set(cx - 2, sy(16), 3, st(stoneStairs, "east", "bottom"));
    set(cx - 2, sy(17), 3, stoneA);
    set(cx + 2, sy(16), 3, st(stoneStairs, "west", "bottom"));
    set(cx + 2, sy(17), 3, stoneA);

    // Crested Battle-Crown & Horns (dy = 19..24)
    fillBox(cx - 2, sy(19), 4, cx + 2, sy(21), 6, stoneA);
    set(cx - 2, sy(19), 3, stoneA);
    set(cx - 1, sy(19), 3, gilded);
    set(cx, sy(19), 3, magma);
    set(cx + 1, sy(19), 3, gilded);
    set(cx + 2, sy(19), 3, stoneA);

    for (let dy = 20; dy <= 22; dy++) {
      set(cx, sy(dy), 3, (dy === 21) ? magma : stoneA);
      set(cx, sy(dy), 4, stoneA);
      set(cx, sy(dy), 5, stoneA);
    }
    set(cx, sy(23), 4, stoneWall);
    set(cx, sy(24), 4, stoneWall);
    set(cx, sy(23), 5, st(stoneStairs, "south", "bottom"));
    set(cx, sy(23), 3, st(stoneStairs, "north", "bottom"));

    // Angular Horns
    set(cx - 3, sy(20), 4, st(stoneStairs, "east", "top"));
    set(cx - 3, sy(21), 4, stoneWall);
    set(cx - 4, sy(22), 4, stoneWall);
    set(cx - 4, sy(23), 4, st(stoneStairs, "west", "top"));

    set(cx + 3, sy(20), 4, st(stoneStairs, "west", "top"));
    set(cx + 3, sy(21), 4, stoneWall);
    set(cx + 4, sy(22), 4, stoneWall);
    set(cx + 4, sy(23), 4, st(stoneStairs, "east", "top"));
  }

  buildDwarfSentinel(7);
  buildDwarfSentinel(24);

  // =========================================================================
  // 6. UPPER BASTIONS, MACHICOLATIONS & HOLD CREST (dy = 22..27)
  // =========================================================================
  for (let x = 2; x <= 29; x++) {
    set(x, sy(22), 5, (x % 4 === 0) ? gilded : stoneA);
    set(x, sy(22), 6, stoneP);

    if (x % 2 === 0) {
      set(x, sy(23), 4, st(stoneStairs, "north", "top"));
    } else {
      set(x, sy(23), 4, sl(stoneSlab, "top"));
    }
    fillBox(x, sy(23), 5, x, sy(23), 8, stoneP);

    // Battlement walk
    fillBox(x, sy(24), 4, x, sy(24), 8, pave);

    // Merlons
    if (x % 2 === 0) {
      set(x, sy(25), 4, stoneA);
      set(x, sy(26), 4, sl(stoneSlab, "bottom"));
    } else {
      set(x, sy(25), 4, stoneWall);
    }
  }

  // Raised Watch Turrets with Soul Fire Pyres (Left & Right)
  function buildTurret(x0, x1) {
    fillBox(x0, sy(25), 4, x1, sy(26), 6, stoneA);
    const tcx = Math.floor((x0 + x1) / 2);
    set(tcx, sy(26), 5, anvilN);
    set(tcx, sy(27), 5, soulCampfire);
    for (let x = x0; x <= x1; x++) {
      set(x, sy(27), 4, stoneWall);
      set(x, sy(27), 6, stoneWall);
    }
    set(x0, sy(27), 5, stoneWall);
    set(x1, sy(27), 5, stoneWall);
  }
  buildTurret(1, 3);
  buildTurret(28, 30);

  // Stepped Gatehouse Crest & Great Fire Pyre (X = 13..18, dy = 24..27)
  fillBox(13, sy(24), 4, 18, sy(26), 7, stoneP);
  set(13, sy(26), 4, st(stoneStairs, "east", "bottom"));
  set(14, sy(26), 4, stoneA);
  set(15, sy(26), 4, magma);
  set(16, sy(26), 4, magma);
  set(17, sy(26), 4, stoneA);
  set(18, sy(26), 4, st(stoneStairs, "west", "bottom"));

  set(14, sy(27), 4, st(stoneStairs, "east", "bottom"));
  set(15, sy(27), 4, gilded);
  set(16, sy(27), 4, gilded);
  set(17, sy(27), 4, st(stoneStairs, "west", "bottom"));

  set(15, sy(27), 5, anvilE);
  set(16, sy(27), 5, anvilE);
  set(15, sy(27), 6, campfire);
  set(16, sy(27), 6, campfire);

  // =========================================================================
  // 7. FORECOURT BRAZIERS & ANVILS (dy = 0..4)
  // =========================================================================
  const brazierLocs = [
    [2, 1],
    [9, 0],
    [22, 0],
    [29, 1],
  ];

  for (let [bx, bz] of brazierLocs) {
    set(bx, sy(0), bz, plinth);
    set(bx, sy(1), bz, plinth);
    set(bx, sy(2), bz, stoneWall);
    set(bx, sy(3), bz, anvilN);
    set(bx, sy(4), bz, soulCampfire);
    if (bx > 0) set(bx - 1, sy(1), bz, st(stoneStairs, "east", "bottom"));
    if (bx < W - 1) set(bx + 1, sy(1), bz, st(stoneStairs, "west", "bottom"));
  }

  set(11, sy(2), 4, anvilN);
  set(20, sy(2), 4, anvilN);
  set(11, sy(3), 4, lanternFloor);
  set(20, sy(3), 4, lanternFloor);

  // =========================================================================
  // 8. TERRAIN CONFORMITY PASS (Rule 6 - Slopes, Ridges & Shoreline)
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null && grid[x][y][z] !== "minecraft:air") {
          if (minY === -1) minY = y;
        }
      }

      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + h)));

      if (minY !== -1) {
        if (groundY < minY) {
          const foundationBlock = (z >= 10) ? stoneP : plinth;
          for (let y = groundY; y < minY; y++) {
            set(x, y, z, foundationBlock);
          }
        }
      } else {
        if (z <= 8 && groundY < sy(2)) {
          set(x, groundY, z, pave);
        }
      }
    }
  }

  // Extend front entrance steps down to terrain if ground drops at Z=0
  for (let x = 12; x <= 19; x++) {
    const h0 = api.heightAt(x, 0);
    const g0 = Math.max(0, Math.min(sy(2), Math.round(seatY + h0)));
    for (let y = g0; y < sy(0); y++) {
      set(x, y, 0, st(groundStairs, "north"));
    }
  }

  // =========================================================================
  // 9. EMIT BLOCKS TO API
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[x][y][z];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "monumental_dwarf_gate",
    seatY: seatY,
    anchors: {
      front: [15, sy(1), 0],
      door: [15, sy(2), 8],
    },
    interiors: [
      {
        min: [13, sy(3), 10],
        max: [18, sy(10), 17],
        kind: "vault",
      },
    ],
  };
}

magma_sluice_forge.source:
export const envelope = [26, 28, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 6;
  const fy = (lvl) => SEAT_Y + lvl;

  // Resolve palette roles with authentic dwarven volcanic materials
  const P = {
    stone: api.theme.stone.primary || "minecraft:polished_blackstone_bricks",
    accent: api.theme.stone.accent || "minecraft:gilded_blackstone",
    stairs: api.theme.stone.stairs || "minecraft:polished_blackstone_brick_stairs",
    slab: api.theme.stone.slab || "minecraft:polished_blackstone_brick_slab",
    wall: api.theme.stone.wall || "minecraft:polished_blackstone_wall",
    pavement: api.theme.ground.pavement || "minecraft:polished_blackstone",
    plinth: api.theme.ground.plinth || "minecraft:blackstone",
    kerb: api.theme.ground.kerb || "minecraft:polished_blackstone",
    roofSolid: api.theme.roof.solid || "minecraft:deepslate_tiles",
    roofStairs: api.theme.roof.stairs || "minecraft:deepslate_tile_stairs",
    roofSlab: api.theme.roof.slab || "minecraft:deepslate_tile_slab",
    wallCore: api.theme.wall.core || "minecraft:deepslate_bricks",
    wallMerlon: api.theme.wall.merlon || "minecraft:polished_blackstone_bricks",
    wallParapet: api.theme.wall.parapet || "minecraft:polished_blackstone_wall",
    woodPlanks: api.theme.wood.planks || "minecraft:spruce_planks",
    woodFence: api.theme.wood.fence || "minecraft:nether_brick_fence",
    magma: "minecraft:magma_block",
    bars: "minecraft:iron_bars",
    chain: "minecraft:chain[axis=y]",
    anvilN: "minecraft:anvil[facing=north]",
    anvilE: "minecraft:chipped_anvil[facing=east]",
    blastFurnaceE: "minecraft:blast_furnace[facing=east,lit=true]",
    blastFurnaceW: "minecraft:blast_furnace[facing=west,lit=true]",
    campfire: "minecraft:campfire[lit=true,signal_fire=true]",
    hay: "minecraft:hay_block",
    cryingObsidian: "minecraft:crying_obsidian",
    gildedBlackstone: "minecraft:gilded_blackstone",
    lanternHang: "minecraft:lantern[hanging=true]",
    lanternFloor: "minecraft:lantern[hanging=false]",
    cauldron: "minecraft:cauldron"
  };

  function stair(facing, half = "bottom", shape = "straight") {
    const base = P.stairs.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }
  function roofStair(facing, half = "bottom", shape = "straight") {
    const base = P.roofStairs.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }
  function slab(type = "bottom") {
    const base = P.slab.split("[")[0];
    return `${base}[type=${type}]`;
  }
  function roofSlab(type = "bottom") {
    const base = P.roofSlab.split("[")[0];
    return `${base}[type=${type}]`;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function fill(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  function isFootprint(x, z) {
    if (x >= 3 && x <= 22 && z >= 4 && z <= 20) return true;
    if (x >= 8 && x <= 17 && z >= 0 && z <= 3) return true;
    if (x >= 8 && x <= 17 && z >= 21 && z <= 23) return true;
    if ((x >= 1 && x <= 5 || x >= 20 && x <= 24) && (z >= 3 && z <= 7 || z >= 17 && z <= 21)) return true;
    return false;
  }

  // 1. Terrain adaptation & foundation skirt
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isFootprint(x, z)) {
        const h = Math.round(api.heightAt(x, z));
        const gy = Math.max(0, Math.min(H - 1, SEAT_Y + h));
        if (gy < SEAT_Y) {
          for (let y = gy; y < SEAT_Y; y++) {
            set(x, y, z, P.plinth);
          }
        } else if (gy > SEAT_Y) {
          for (let y = SEAT_Y; y <= gy; y++) {
            set(x, y, z, P.plinth);
          }
        }
      }
    }
  }

  // 2. Main Floor & Stepped Entrance Forecourt
  fill(3, fy(0), 4, 22, fy(0), 20, P.stone);
  for (let x = 4; x <= 21; x++) {
    for (let z = 5; z <= 19; z++) {
      const isCheck = (x + z) % 2 === 0;
      set(x, fy(0), z, isCheck ? P.pavement : P.stone);
    }
  }

  // Entrance steps & terrace (Z = 0..3)
  fill(8, fy(0), 2, 17, fy(0), 3, P.pavement);
  for (let x = 9; x <= 16; x++) {
    set(x, fy(0), 1, stair("south"));
    set(x, fy(0) - 1, 1, P.plinth);
    set(x, fy(0) - 1, 0, stair("south"));
  }
  // Forecourt flanking guard piers
  fill(8, fy(0), 1, 8, fy(2), 2, P.stone);
  fill(17, fy(0), 1, 17, fy(2), 2, P.stone);
  set(8, fy(3), 1, P.wall);
  set(17, fy(3), 1, P.wall);
  set(8, fy(4), 1, P.lanternFloor);
  set(17, fy(4), 1, P.lanternFloor);

  // 3. Massive Corner Bastions (Stepped Massing)
  const bastions = [
    { x1: 1, z1: 3, x2: 4, z2: 6 },
    { x1: 21, z1: 3, x2: 24, z2: 6 },
    { x1: 1, z1: 18, x2: 4, z2: 21 },
    { x1: 21, z1: 18, x2: 24, z2: 21 }
  ];

  for (const b of bastions) {
    fill(b.x1, fy(0), b.z1, b.x2, fy(4), b.z2, P.wallCore);
    // Quoins and accents
    for (let y = fy(0); y <= fy(4); y++) {
      set(b.x1, y, b.z1, P.accent);
      set(b.x2, y, b.z1, P.accent);
      set(b.x1, y, b.z2, P.accent);
      set(b.x2, y, b.z2, P.accent);
    }
    // Mid tier (inset)
    const mx1 = b.x1 < 10 ? b.x1 + 1 : b.x1;
    const mx2 = b.x1 < 10 ? b.x2 : b.x2 - 1;
    const mz1 = b.z1 < 10 ? b.z1 + 1 : b.z1;
    const mz2 = b.z1 < 10 ? b.z2 : b.z2 - 1;

    fill(mx1, fy(5), mz1, mx2, fy(9), mz2, P.stone);
    // Upper tier & machicolation
    fill(mx1, fy(10), mz1, mx2, fy(13), mz2, P.wallCore);
    for (let x = mx1; x <= mx2; x++) {
      for (let z = mz1; z <= mz2; z++) {
        set(x, fy(14), z, P.stone);
      }
    }
    set(mx1, fy(15), mz1, P.wallMerlon);
    set(mx2, fy(15), mz1, P.wallMerlon);
    set(mx1, fy(15), mz2, P.wallMerlon);
    set(mx2, fy(15), mz2, P.wallMerlon);
  }

  // 4. Outer Walls & Great North Facade (Y = fy(0)..fy(12))
  // North Wall
  fill(4, fy(0), 4, 21, fy(12), 4, P.stone);
  // Arrow slits on North facade
  set(7, fy(3), 4, P.bars);
  set(7, fy(4), 4, P.bars);
  set(18, fy(3), 4, P.bars);
  set(18, fy(4), 4, P.bars);
  // Great Portal (X = 11..14, Z = 4)
  fill(11, fy(1), 4, 14, fy(4), 4, "minecraft:air");
  fill(11, fy(0), 4, 11, fy(5), 4, P.accent);
  fill(14, fy(0), 4, 14, fy(5), 4, P.accent);
  set(11, fy(5), 4, stair("east", "top"));
  set(14, fy(5), 4, stair("west", "top"));
  set(12, fy(5), 4, slab("top"));
  set(13, fy(5), 4, slab("top"));
  // Raised iron portcullis inside top arch
  fill(12, fy(4), 4, 13, fy(4), 4, P.bars);

  // South Wall (Z = 20)
  fill(4, fy(0), 20, 21, fy(12), 20, P.stone);
  // Culvert opening for magma aqueduct and lower service tunnel
  fill(11, fy(1), 20, 14, fy(3), 20, "minecraft:air");
  set(11, fy(3), 20, stair("east", "top"));
  set(14, fy(3), 20, stair("west", "top"));

  // West Wall (X = 3..4) & East Wall (X = 21..22)
  fill(3, fy(0), 4, 4, fy(12), 20, P.stone);
  fill(21, fy(0), 4, 22, fy(12), 20, P.stone);
  // Side embrasures / windows
  fill(3, fy(4), 10, 4, fy(6), 10, P.bars);
  fill(3, fy(4), 15, 4, fy(6), 15, P.bars);
  fill(21, fy(4), 10, 22, fy(6), 10, P.bars);
  fill(21, fy(4), 15, 22, fy(6), 15, P.bars);

  // 5. Interior Pillars and Vault Arches
  const pillars = [
    { x: 8, z: 8 },
    { x: 17, z: 8 },
    { x: 8, z: 14 },
    { x: 17, z: 14 }
  ];

  for (const p of pillars) {
    fill(p.x, fy(0), p.z, p.x, fy(6), p.z, P.wallCore);
    set(p.x, fy(1), p.z, P.accent);
    // Base plinth
    set(p.x, fy(0), p.z - 1, stair("south"));
    set(p.x, fy(0), p.z + 1, stair("north"));
    set(p.x - 1, fy(0), p.z, stair("east"));
    set(p.x + 1, fy(0), p.z, stair("west"));
    // Capital corbels
    set(p.x, fy(6), p.z - 1, stair("north", "top"));
    set(p.x, fy(6), p.z + 1, stair("south", "top"));
    set(p.x - 1, fy(6), p.z, stair("west", "top"));
    set(p.x + 1, fy(6), p.z, stair("east", "top"));
    // Ceiling vault arches
    fill(p.x, fy(7), p.z - 2, p.x, fy(7), p.z + 2, P.stone);
    fill(p.x - 2, fy(7), p.z, p.x + 2, fy(7), p.z, P.stone);
  }

  // 6. Magma Sluice Aqueduct, Sluice Gate & Forge Crucibles
  // Sluice Aqueduct running from mountain cliff (Z=23) to central hall
  fill(10, fy(4), 16, 15, fy(4), 23, P.stone);
  fill(11, fy(5), 16, 14, fy(5), 23, P.magma);
  for (let z = 16; z <= 23; z++) {
    set(11, fy(5), z, z % 3 === 0 ? P.gildedBlackstone : P.magma);
    set(14, fy(5), z, z % 4 === 0 ? P.cryingObsidian : P.magma);
    // Channel kerbs
    set(10, fy(5), z, P.stone);
    set(10, fy(6), z, stair("west"));
    set(15, fy(5), z, P.stone);
    set(15, fy(6), z, stair("east"));
  }

  // Magma cascade stepping down into forge crucible (Z = 15 down to 10)
  set(12, fy(4), 15, P.magma);
  set(13, fy(4), 15, P.magma);
  set(12, fy(3), 14, P.magma);
  set(13, fy(3), 14, P.magma);
  set(12, fy(2), 13, P.magma);
  set(13, fy(2), 13, P.magma);
  set(12, fy(1), 12, P.magma);
  set(13, fy(1), 12, P.magma);
  set(12, fy(1), 11, P.magma);
  set(13, fy(1), 11, P.magma);

  // Crucible curb & iron grating
  fill(11, fy(1), 10, 14, fy(1), 13, P.stone);
  fill(12, fy(1), 11, 13, fy(1), 12, P.magma);
  fill(12, fy(2), 11, 13, fy(2), 12, P.bars);
  set(11, fy(1), 11, P.accent);
  set(14, fy(1), 11, P.accent);
  set(11, fy(1), 12, P.accent);
  set(14, fy(1), 12, P.accent);

  // Sluice Gate Pylons & Guillotine Mechanism (Z = 16)
  fill(9, fy(0), 16, 10, fy(15), 16, P.stone);
  fill(15, fy(0), 16, 16, fy(15), 16, P.stone);
  // Winch bridge over gate
  fill(10, fy(12), 16, 15, fy(13), 16, P.accent);
  set(12, fy(14), 16, P.wall);
  set(13, fy(14), 16, P.wall);
  // Sluice Gate suspended plate
  fill(11, fy(7), 16, 14, fy(9), 16, P.plinth);
  fill(12, fy(7), 16, 13, fy(9), 16, P.accent);
  // Suspension Chains
  fill(12, fy(10), 16, 12, fy(12), 16, P.chain);
  fill(13, fy(10), 16, 13, fy(12), 16, P.chain);

  // 7. Master Anvil & Side Blast Furnaces
  // Great Master Anvil Complex (X = 12..13, Z = 8..9)
  fill(12, fy(0), 8, 13, fy(0), 9, P.accent);
  set(12, fy(1), 8, P.stone);
  set(13, fy(1), 8, P.stone);
  set(12, fy(2), 8, P.anvilN);
  set(13, fy(2), 8, P.anvilE);

  // West Blast Furnaces (X = 5, Z = 7..9)
  fill(5, fy(0), 7, 5, fy(0), 9, P.plinth);
  set(5, fy(1), 7, P.blastFurnaceE);
  set(5, fy(1), 8, P.blastFurnaceE);
  set(5, fy(1), 9, P.blastFurnaceE);
  fill(5, fy(2), 7, 5, fy(4), 9, P.stone);
  set(5, fy(2), 7, stair("east", "top"));
  set(5, fy(2), 9, stair("east", "top"));

  // East Blast Furnaces (X = 20, Z = 7..9)
  fill(20, fy(0), 7, 20, fy(0), 9, P.plinth);
  set(20, fy(1), 7, P.blastFurnaceW);
  set(20, fy(1), 8, P.blastFurnaceW);
  set(20, fy(1), 9, P.blastFurnaceW);
  fill(20, fy(2), 7, 20, fy(4), 9, P.stone);
  set(20, fy(2), 7, stair("west", "top"));
  set(20, fy(2), 9, stair("west", "top"));

  // Quench Cauldrons
  set(8, fy(1), 11, P.cauldron);
  set(17, fy(1), 11, P.cauldron);

  // 8. Mezzanine Gallery & Access Stairs (Y = fy(7))
  // North catwalk
  fill(5, fy(7), 5, 20, fy(7), 5, P.woodPlanks);
  for (let x = 6; x <= 19; x++) set(x, fy(8), 5, P.bars);
  // South catwalk & sluice bridge
  fill(5, fy(7), 15, 9, fy(7), 15, P.stone);
  fill(16, fy(7), 15, 20, fy(7), 15, P.stone);
  fill(10, fy(8), 15, 15, fy(8), 15, P.stone);
  fill(5, fy(8), 15, 9, fy(8), 15, P.bars);
  fill(16, fy(8), 15, 20, fy(8), 15, P.bars);
  // Stairs to mezzanine
  for (let i = 0; i < 6; i++) {
    set(6, fy(1) + i, 10 + i, stair("south"));
    fill(6, fy(0), 10 + i, 6, fy(0) + i, 10 + i, P.plinth);
    set(19, fy(1) + i, 10 + i, stair("south"));
    fill(19, fy(0), 10 + i, 19, fy(0) + i, 10 + i, P.plinth);
  }

  // 9. Roof Platform & Parapets (Y = fy(12)..fy(14))
  fill(4, fy(12), 4, 21, fy(12), 20, P.roofSolid);
  // Parapet walls and merlons
  for (let x = 4; x <= 21; x++) {
    set(x, fy(13), 4, (x % 2 === 0) ? P.wallMerlon : P.wallParapet);
    set(x, fy(13), 20, (x % 2 === 0) ? P.wallMerlon : P.wallParapet);
  }
  for (let z = 4; z <= 20; z++) {
    set(4, fy(13), z, (z % 2 === 0) ? P.wallMerlon : P.wallParapet);
    set(21, fy(13), z, (z % 2 === 0) ? P.wallMerlon : P.wallParapet);
  }
  // Central Clerestory / Ventilation Monitor
  fill(9, fy(13), 7, 16, fy(14), 13, P.stone);
  fill(10, fy(13), 8, 15, fy(13), 12, "minecraft:air");
  fill(10, fy(14), 7, 15, fy(14), 7, P.bars);
  fill(10, fy(14), 13, 15, fy(14), 13, P.bars);
  fill(9, fy(15), 7, 16, fy(15), 13, P.roofSlab);

  // 10. The Three Smoke Chimneys with Billowing Signal Fire Smoke
  // West Chimney (X = 5..7, Z = 7..9)
  fill(5, fy(10), 7, 7, fy(18), 9, P.stone);
  fill(6, fy(10), 8, 6, fy(19), 8, "minecraft:air");
  set(6, fy(15), 8, P.hay);
  set(6, fy(16), 8, P.campfire);
  set(5, fy(19), 7, P.wall);
  set(7, fy(19), 7, P.wall);
  set(5, fy(19), 9, P.wall);
  set(7, fy(19), 9, P.wall);
  set(6, fy(19), 8, roofSlab("top"));

  // East Chimney (X = 18..20, Z = 7..9)
  fill(18, fy(10), 7, 20, fy(18), 9, P.stone);
  fill(19, fy(10), 8, 19, fy(19), 8, "minecraft:air");
  set(19, fy(15), 8, P.hay);
